def score(program: str) -> float:
    try:
        import ast
        tree = ast.parse(program)
        node_count = sum(1 for _ in ast.walk(tree))
        return min(node_count / 150.0, 1.0)
    except:
        return 0.0

def score(program: str) -> float:
    n = len(program)
    return max(0, min(1, 0.8 - n / 1500))

def score(program: str) -> float:
